const additions = {
  // Cat 1: Opsta medicina (91-95)
  91: `\n\nСОВРЕМЕНИ ПРИСТАПИ И ИДНИНА. Дијабетесот тип 2 кај младите бара мултидисциплинарен пристап. Едукацијата за исхрана и физичка активност треба да започне во училиште. Родителите играат клучна улога во создавањето здрави навики кај децата. Најновите истражувања покажуваат дека интервален пост и медитеранска исхрана ја подобруваат инсулинската чувствителност. Континуираните монитори за гликоза стануваат сè подостапни. Вештачкиот панкреас, систем кој го автоматизира внесот на инсулин, го менува третманот на дијабетес. Терапијата со GLP-1 агонисти помага и во контрола на тежината кај млади пациенти. Метаболичката хирургија е опција за млади со тешка дебелина и дијабетес. Генетското тестирање може да идентификува ризик пред болеста да се развие. Психолошката поддршка за справување со хроничната дијагноза е од суштинско значење. Групите за поддршка овозможуваат размена на искуства. Иднината носи персонализирана медицина базирана на генетски профил. Напредокот во терапијата со матични клетки ветува потенцијално лекување во иднина. Препораките на европските здруженија за дијабетес се дотеруваат секоја година врз основа на нови докази.`,
  92: `\n\nЗНАЧЕЊЕ И ПЕРСПЕКТИВИ. Систематскиот скрининг за рак во примарната заштита го намалува товарот на болеста. Матичниот лекар е првата линија на одбрана. Редовните превентивни прегледи вклучуваат мамографија за жени после 40 години. Папа тестовите за рак на грло на матка се задолжителни на секои 3 години. ХПВ вакцинацијата на адолесценти превенира рак на грло на матка. Колоноскопијата за скрининг на колоректален рак се препорачува од 45 години. Новите тестови на столица се неинвазивна алтернатива. Психолошката поддршка го намалува стравот од скрининг. Мобилните единици го зголемуваат пристапот во рурални подрачја. Иднината носи тестови на крв за откривање на повеќе видови рак истовремено. Вештачката интелигенција ја подобрува точноста на мамографијата. Скринингот за рак на бели дробови со КТ скен со ниска доза се воведува кај пушачи. Националните програми со покани и потсетници го зголемуваат одѕивот. Едукацијата за самопреглед е важна, но не го заменува редовниот скрининг. Инвестициите во скрининг програми се исплатливи преку намалени трошоци за лекување напреднат рак. Медицинските сестри во заедницата играат клучна улога во скринингот на ранливи популации.`,
  93: `\n\nИНТЕГРИРАН ПРИСТАП. Мултиморбидитетот бара холистичко гледање на пациентот. Наместо да се третира секоја болест одделно, фокусот треба да биде на целокупното здравје и квалитет на живот. Падот на постарите лица се спречува со вежби за рамнотежа и прилагодување на домот. Полифармацијата мора редовно да се ревидира од матичниот лекар. Нутритивниот статус треба да се проценува при секоја посета. Анемијата е честа и лекувачка причина за замор кај постари. Деменцијата често коегзистира со други болести. Интеграцијата на социјални работници во тимот е клучна. Палијативната грижа треба да се вклучи рано, не само на крајот. Физикалната терапија го одржува функционирањето. Когнитивниот тренинг го забавува падот. Управувањето со болка бара внимателен пристап поради ризик од несакани ефекти. Семејната поддршка е неопходна за успешно управување. Телемедицината овозможува редовно следење без патување. Здравствените системи мора да се прилагодат на стареењето на популацијата преку развој на геријатриски услуги. Редовната проценка на когнитивниот статус треба да биде стандардна процедура во примарната заштита.`,
  94: `\n\nГЛОБАЛНА ЗАКАНА. Антибиотската резистенција е една од најголемите закани за современата медицина. Бактериите отпорни на повеќе лекови предизвикуваат инфекции кои тешко се третираат. Метицилин-резистентниот стафилокок е чест во болниците. Повеќето настинки и грипови се вирусни и не бараат антибиотици. Кратките курсеви на антибиотици се подеднакво ефикасни како долгите. Брзите тестови за стрептокок помагаат во донесување одлуки. Злоупотребата на антибиотици во сточарството е значаен проблем. Бактериофагите се ветувачка алтернатива која се истражува. Антимикробните пептиди од природно потекло исто така покажуваат потенцијал. Вакцинацијата го намалува бројот на бактериски инфекции и потребата од антибиотици. Едукацијата на пациентите за правилна употреба е клучна. Матичниот лекар има централна улога во рационалното препишување. Чистењето на рацете останува наједноставната превентивна мерка. Иднината носи нови антибиотици во комбинација со ензимски инхибитори за надминување на резистенција. Лабораториските тестови за Ц-реактивен протеин и прокалцитонин помагаат да се разликува вирусна од бактериска инфекција, што го намалува непотребното препишување антибиотици.`,
  95: `\n\nДИГИТАЛНА ТРАНСФОРМАЦИЈА. Телемедицината брзо еволуираше за време на пандемијата. Денес, таа е составен дел на здравствената грижа. Виртуелните консултации се ефикасни за контрола на хронични состојби. Заштедата на време и пари за пациентите е значајна. Електронските здравствени записи овозможуваат непречена комуникација. Теледерматологијата користи фотографии за дијагноза на кожни болести. Телепсихијатријата го зголемува пристапот до ментално здравје. Носливите уреди овозможуваат континуиран мониторинг на витални параметри. Телемедицината не е погодна за итни ситуации. Акутните состојби бараат физички преглед. Дигиталната писменост на пациентите претставува ограничување. Регулативата за телемедицина се развива за да обезбеди безбедност и квалитет. Едукацијата на лекарите за спроведување виртуелни прегледи е неопходна. Иднината носи интеграција на вештачка интелигенција за поддршка на одлуките. Телемедицината нема да ја замени традиционалната грижа, туку ќе ја направи подостапна и поефикасна. Кибер-безбедноста станува приоритет за заштита на здравствените податоци во дигиталната ера.`,

  // Cat 2: Kardiologija (96-100)
  96: `\n\nДИЈАГНОСТИЧКИ И ТЕРАПЕВТСКИ ПРИСТАП. HFpEF дијагнозата бара висок степен на сомнеж. Симптомите како отежнато дишење и замор се неспецифични. Ехокардиографијата со доплер студија е клучна за дијагноза. Мерењето на натриуретски пептиди помага во диференцијација. SGLT2 инхибиторите даваат надеж, намалувајќи хоспитализации. Третманот со диуретици ги контролира симптомите на конгестија. Контролата на крвниот притисок и дијабетес е важна. Програмите за кардиоваскуларна рехабилитација го подобруваат капацитетот за вежбање. Губењето на тежина значително ги подобрува симптомите. Истражувањата продолжуваат со нови молекули. Фокусот е на специфични фенотипови на HFpEF. Персонализираниот пристап базиран на биомаркери е иднината. Клучни се рана дијагноза и мултидисциплинарен пристап. Пациентите треба активно да учествуваат во управувањето со својата состојба. Редовното мерење на телесната тежина е важен показател за влошување на срцевата слабост, бидејќи зголемувањето укажува на задршка на течности.`,
  97: `\n\nРАНА ДЕТЕКЦИЈА. Хипертензијата кај млади е често асимптоматска. Редовното мерење на крвниот притисок е единствениот начин за откривање. Амбулаторното 24-часовно мерење дава точна дијагноза. Младите со семејна историја на хипертензија се под зголемен ризик. Промената на животните навики е прв чекор. DASH диетата со низок внес на сол го намалува притисокот. Намалувањето на телесната тежина за 5% значително помага. Алкохолот и кофеинот може да го зголемат притисокот. Адхеренцијата кон терапија е предизвик кај младите. ACE инхибиторите и блокаторите на калциумови канали се прва линија. Редовното следење овозможува прилагодување на третманот. Нелекуваната хипертензија доведува до оштетување на срцето, бубрезите и мозокот. Едукацијата за важноста на контролата на притисокот е клучна. Иднината носи персонализиран пристап базиран на генетски фактори. Младите треба да го сфатат крвниот притисок сериозно од рана возраст. Маскираната хипертензија, кога притисокот е нормален во ординација но висок надвор, е особено честа кај младите и бара амбулаторно мерење.`,
  98: `\n\nДИЈАГНОСТИЧКИ МЕТОДИ. КТ коронарна ангиографија е брза и прецизна дијагностичка алатка. Се користи јодиран контраст за визуелизација на коронарните артерии. Високата негативна предиктивна вредност значи дека нормалниот наод исклучува коронарна болест. Калциум скорот дава информација за атеросклеротичниот товар. Високиот калциум скор е силен предиктор за кардиоваскуларни настани. КТ ангиографијата го намалува бројот на непотребни катетеризации. Статините ги намалуваат LDL холестеролот и го стабилизираат плакот. Аспиринот се користи за секундарна превенција кај позната коронарна болест. Медитеранската исхрана го намалува ризикот од коронарно срцево заболување. Физичката активност од 30 минути дневно е задолжителна за кардиоваскуларно здравје. Контролата на крвниот притисок и дијабетес се основни во превенцијата. Пушењето е најсилниот превентибилен фактор на ризик. Редовните кардиолошки контроли се препорачуваат по 40 години. ЕГЕТ тестот и стрес ехокардиографијата остануваат важни функционални тестови за проценка на исхемија кај пациенти со интермедијарен ризик.`,
  99: `\n\nТЕХНИКИ И ИСХОДИ. Катетер аблацијата е минимално инвазивна процедура за лекување на атријална фибрилација. Се вметнува катетер преку феморална вена до срцето. Со радиофреквентна енергија се изолираат пулмоналните вени. Успешноста за пароксизмална АФ е 70-80%. Новата техника на пулсирачко поле аблација е побезбедна. Криобалон аблацијата нуди алтернатива со замрзнување. Пациентите се отпуштени истиот ден или следниот ден. Продолжуваат со антикоагулантна терапија по процедурата. Рецидивите се можни во првите три месеци. Лајфстајл промените како намалување на тежината го намалуваат ризикот. CHADS2-VASc скорот го одредува ризикот од мозочен удар. Новите DOAC лекови се преферираат над варфаринот. Иднината носи персонализирани пристапи за секој пациент со атријална фибрилација. Електричната кардиоверзија останува опција за акутно враќање на синусниот ритам кај хемодинамски нестабилни пациенти или кога аблацијата не е успешна.`,
  100: `\n\nЕКОЛОШКИ РИЗИК ФАКТОРИ. Загадувањето на воздухот е значаен фактор за кардиоваскуларна смрт. Фините ПМ2.5 честички предизвикуваат системско воспаление. Краткотрајната изложеност на високо загадување го зголемува ризикот од срцев удар. Долгорочната изложеност го забрзува развојот на атеросклероза. Пациентите со постоечки срцеви заболувања се најранливи. Индивидуалната заштита вклучува следење на индексот за квалитет на воздух. Избегнувањето на надворешни активности во денови со високо загадување е препорачливо. Прочистувачите на воздух во домовите го намалуваат ризикот. Зелените површини во градовите го намалуваат загадувањето. Урбаното планирање треба да промовира одржлив транспорт. Здравствените работници треба да ги советуваат пациентите за ризиците. Потребни се поефикасни регулативи за намалување на емисиите од индустрија и сообраќај. Иднината носи чисти технологии и позелени градови, што ќе го подобри кардиоваскуларното здравје на популацијата. Бучавата од сообраќај е дополнителен кардиоваскуларен ризик што се поврзува со зголемен крвен притисок и стрес.`,

  // Cat 3: Nevrologija (101-105)
  101: `\n\nСОВРЕМЕН ТРЕТМАН. Мултипла склероза бара рана дијагноза и агресивен третман. МРИ на мозок и рбетен мозок е клучна за дијагноза и следење. Новите орални терапии го олеснуваат третманот за пациентите. Моноклоналните антитела високо ги намалуваат рецидивите. Рехабилитацијата е суштинска за одржување на функцијата. Физикалната терапија ја подобрува мобилноста. Раниот третман го забавува напредувањето на болеста. Истражувањата за поправка на миелин ветуваат за иднината. Поддршката од групи за пациенти е важна. Когнитивниот тренинг помага за зачувување на менталните функции. Невропсихолошката проценка е дел од сеопфатниот пристап. Едукацијата за управување со заморот е клучна. Семејната поддршка игра значајна улога. Иднината носи персонализиран пристап базиран на биомаркери и генетски профил. Бремените жени со мултипла склероза имаат добра прогноза бидејќи во бременоста стапката на рецидиви е природно намалена.`,
  102: `\n\nФАКТОРИ НА РИЗИК. Мозочниот удар кај млади бара етиолошка дијагноза. Дисекција на каротидна артерија е честа причина. Кардиоемболизам од отворен форамен овале исто така. Злоупотребата на дроги и алкохол го зголемува ризикот. Оралните контрацептиви кај пушачите се значаен фактор. Мигрената со аура го зголемува ризикот. Исхемичниот удар се третира со тромболиза во првите 4.5 часа. Механичката тромбектомија е опција за големи оклузии. Превенцијата вклучува контрола на факторите на ризик. Антиагрегационата терапија е основа на секундарната превенција. Рехабилитацијата започнува рано во болница. Логопедскиот третман после мозочен удар е важен. Промената на навиките го намалува ризикот од втор удар. Едукацијата за рано препознавање на симптомите е клучна за спасување животи. ФАСТ скринингот за рано препознавање на симптомите на мозочен удар треба да го познава секој граѓанин.`,
  103: `\n\nПРЕВЕНЦИЈА И ТРЕТМАН. ЦГРП инхибиторите се револуционерна превентивна терапија. Моноклоналните антитела се администрираат еднаш месечно. Гепантите се орални лекови за акутен третман без вазоконстрикција. Триптаните остануваат ефикасни за акутна мигрена. Превенцијата вклучува и промени во навиките. Редовниот сон е најважниот превентибилен фактор. Редовните оброци и хидратација го намалуваат ризикот. Избегнувањето на предизвикувачи како одредена храна и стрес помага. Дневникот на главоболки идентификува индивидуални обрасци. Суплементите како магнезиум и рибофлавин помагаат кај некои пациенти. Акупунктурата и бихејвиоралната терапија се дополнителни опции. Новите терапии носат надеж за подобар квалитет на живот. Истражувањата продолжуваат за уште поефикасни лекови. Аеробната физичка активност како брзо одење и пливање, редовно практикувана, го намалува бројот на мигренозни напади кај повеќето пациенти преку регулирање на нивото на серотонин.`,
  104: `\n\nДИЈАГНОЗА И ТРЕТМАН. Паркинсоновата болест се дијагностицира клинички. Треморот во мирување е карактеристичен. Брадикинезијата и ригидноста се присутни. Немоторните симптоми вклучуваат депресија и запек. DaTSCAN помага во диференцијална дијагноза. Леводопата е најефикасен симптоматски третман. Допаминергичните агонисти се користат кај помлади пациенти. Физикалната терапија го одржува одењето и рамнотежата. Логопедската терапија помага кај нарушувања на говорот. Длабоката мозочна стимулација е опција за напредната болест. Несаканите ефекти на долготрајна леводопа вклучуваат дискинезии. Новите терапии се насочени кон модификација на болеста. Анти-алфа синуклеин антителата се во клинички испитувања. Иднината носи генски терапии и биомаркери за рана дијагноза пред да се појават симптоми. Вежбите за рамнотежа и танцовите терапии како танго и бокс прилагоден за пациенти со Паркинсон покажуваат извонредни резултати во подобрување на моторната функција.`,
  105: `\n\nТИПОВИ И ТРЕТМАН. Епилепсијата е нарушување на мозочната активност. Нападите можат да бидат фокални или генерализирани. ЕЕГ е клучна за дијагноза и класификација. МРИ на мозок исклучува структурна причина. Генетското тестирање е корисно кај одредени форми. Новите антиепилептични лекови имаат помалку несакани ефекти. Изборот на лек зависи од типот на напади. Хирургијата нуди лек за резистентна епилепсија. Вагус нерв стимулацијата е алтернативна опција. Кетогената диета е ефикасна кај одредени форми. Безбедноста за време на напад е приоритет. Возењето е забрането додека не се постигне контрола. Повеќето пациенти постигнуваат контрола со правилен третман. Поддршката од семејство и групи за епилепсија е важна. Стигмата околу епилепсија постепено се намалува преку едукација на јавноста. Секој пациент со епилепсија треба да има индивидуален акционен план кој што вклучува инструкции за итна администрација на бензодиазепини кај продолжени напади.`,

  // Cat 4: Pedijatrija (106-110)
  106: `\n\nСОВРЕМЕН ПРИСТАП. Алергиите кај деца се зголемуваат на глобално ниво. Хигиенската хипотеза нуди објаснување за овој тренд. Раното воведување на храна како кикирики превенира алергии. Кожните тестови и специфични IgE помагаат во дијагноза. Оралниот предизвик е златен стандард за потврда. Адреналинскиот автоинјектор е задолжителен за тешки алергии. Едукацијата на родителите за читање декларации е важна. Училиштата треба да имаат планови за итни случаи. Имунотерапијата за храна ветува трајна толеранција. Многу деца прерастат алергија на млеко и јајца. Новите биолошки лекови како омализумаб се користат за тешка алергија. Алергијата на инсекти бара итна интервенција. Пробиотиците може да помогнат кај атопичен дерматитис. Иднината носи персонализирана имунотерапија базирана на генетски профил. Елиминациската диета треба да се спроведува под строг надзор на нутриционист за да се избегнат недостатоци во исхраната на растечкото дете.`,
  107: `\n\nКОНТРОЛА НА БОЛЕСТА. Астмата бара индивидуализиран план за третман. Тригерите вклучуваат алергени, вежбање и респираторни инфекции. Инхалаторните кортикостероиди се основа на контролната терапија. Брзодејствувачките бронходилататори се користат по потреба. Правилната техника на инхалација со спејсер го зголемува ефектот. Мониторингот со ПЕФ мерење помага во следење. Родителите треба да знаат кога да побараат итна помош. Избегнувањето на пасивно пушење е критично. Вакцинацијата против грип и пневмокок се препорачува. Децата со астма треба да бидат активни, со претходна употреба на бронходилататор. Спирометријата го проценува степенот на опструкција. Едукацијата на наставниците за итни случаи е важна. Поголемиот дел од децата со астма водат нормален живот. Раното откривање и третман спречуваат прогресија и ремоделирање на дишните патишта. Алерген-специфичната имунотерапија во форма на сублингвални таблети или инјекции може да ја модифицира природната историја на алергиска астма кај деца.`,
  108: `\n\nПРЕВЕНЦИЈА. Дебелината кај деца е превентибилен здравствен проблем. Балансираната исхрана богата со зеленчук и овошје е основа. Намалувањето на засладени пијалаци дава брзи резултати. Физичката активност од 60 минути дневно е препорака. Ограничувањето на времето пред екран на максимум 2 часа дневно помага. Семејниот пристап во промена на навики е најефикасен. Училишните програми за здрава исхрана и спорт се важни. Редовното следење на раст и развој овозможува рана интервенција. Едукацијата за читање нутритивни декларации помага. Родителите треба да бидат пример за здрави навики. Психолошката поддршка е важна за да се избегне нарушена слика за телото. Здравиот сон од 8-10 часа е неопходен за раст и развој. Комерцијалните диети не се препорачуваат за деца. Третманот вклучува структурирани програми со мултидисциплинарен тим. Готвењето како семејна активност ги учи децата на здрави навики и создава позитивен однос кон храната што трае цел живот.`,
  109: `\n\nРАНА ИНТЕРВЕНЦИЈА. Аутизмот се препознава рано преку развоен скрининг. Првите знаци вклучуваат отсутен очен контакт и доцнење во говорот. Скринингот на 18 и 24 месеци се препорачува за сите деца. Раната дијагноза овозможува рана интервенција. Апликативната бихејвиорална анализа е докажано ефикасна. Интензивната терапија од 20-40 часа неделно носи најдобри резултати. Вклучувањето на родителите во терапијата е од суштинско значење. Логопедската терапија го подобрува говорот. Окупационата терапија помага со сензомоторни проблеми. Инклузивното образование поддржува социјализација. Асистивните технологии како апликации за комуникација се корисни. Невролошкото следење е важно за коморбидитети. Поддршката на семејството преку групи и советување е неопходна. Иднината носи генетско профилирање за персонализирана интервенција. Социјалните приказни и визуелни распореди помагаат во намалување на анксиозноста и подобрување на секојдневното функционирање кај децата со аутизам.`,
  110: `\n\nБЕЗБЕДНОСТ И ЕФИКАСНОСТ. Вакцинацијата е најефикасната превентивна мерка. Вакцините го штитат детето од 14 заразни болести. Колективниот имунитет бара 95% покриеност. Безбедноста на вакцините е темелно проучена и документирана. Несаканите ефекти се обично благи и минливи. Тешките алергиски реакции се исклучително ретки. Дезинформациите за вакцините претставуваат закана за јавното здравје. Родителите треба да се консултираат со педијатар за точна информација. Природниот имунитет по болест не е побезбеден од вакцинацијата. ХПВ вакцината превенира рак на грло на матка. Вакцината против ротавирус спречува тешка дијареја кај доенчиња. Комбинираните вакцини го намалуваат бројот на инјекции. Распоредот за имунизација е научно оптимизиран. Вакцинацијата заштедува милиони животи годишно. Вакцината против варичела и херпес зостер постепено се воведува во националните програми за имунизација на сè повеќе земји.`,

  // Cat 5: Onkologija (111-115)
  111: `\n\nРЕВОЛУЦИЈА ВО ТРЕТМАН. Имунотерапијата го трансформира третманот на рак на белите дробови. Инхибиторите на имуни контролни точки како пембролизумаб и ниволумаб го активираат имуниот систем. Пациентите со висок PD-L1 израз имаат најдобар одговор. Комбинацијата со хемотерапија покажува синергистички ефект. Петгодишното преживување кај напреднат стадиум се зголемува. Несаканите ефекти вклучуваат колентис, хепатитис и пневмонитис. Раното препознавање на автоимуните реакции е клучно. Биомаркерите како тумор мутациски товар го предвидуваат одговорот. Истражувањата продолжуваат за комбинации на имунотерапии. Адјувантната имунотерапија по операција го намалува ризикот од рецидив. Иднината носи персонализирани имунотерапии базирани на неоантигени. Лекувањето со имунотерапија бара редовна проценка на одговорот со КТ скен на секои 8-12 недели. Терапијата продолжува 2 години доколку болеста не напредува.`,
  112: `\n\nПЕРСОНАЛИЗИРАНА МЕДИЦИНА. Геномското профилирање овозможува насочени терапии. Секвенционирањето на следна генерација идентификува мутации во туморот. EGFR мутациите се цел за тирозин киназа инхибитори. ALK транслокациите реагираат на специфични инхибитори. BRCA мутациите укажуваат на осетливост на PARP инхибитори. Течните биопсии од крв овозможуваат неинвазивно следење. Хетерогеноста на туморот претставува предизвик за персонализирана медицина. Резистенцијата на терапија се јавува преку секундарни мутации. Комбинацијата на секвенционирање на РНК и протеомика дава сеопфатна слика. Биопсиите во реално време за време на третманот го следат развојот на резистенција. Генетското советување е важно пред и по тестирањето. Етичките прашања околу генетското тестирање бараат внимателно разгледување. Иднината носи мулти-омикс пристап за целосно профилирање на секој тумор.`,
  113: `\n\nПРЕВЕНЦИЈА И РАНА ДЕТЕКЦИЈА. Колоректалниот рак е превентибилен преку скрининг. Полипите откриени со колоноскопија се отстрануваат пред да станат малигни. Фекалниот имунохемиски тест (ФИТ) се користи годишно. Колоноскопијата на секои 10 години е златен стандард. Новите тестови на столица детектираат туморска ДНК. Семејната историја го зголемува ризикот и бара порано започнување на скринингот. Наследниот неполипозен колоректален рак има специфични критериуми. ЦТ колонографијата е алтернатива кога колоноскопијата е нецелосна. Начинот на живот со вежбање и влакна го намалува ризикот. Црвеното месо и преработените месни производи го зголемуваат ризикот. Аспиринот во мали дози може да има превентивен ефект. Адхеренцијата кон скрининг програмите е сè уште ниска во многу земји. Иднината носи тестови на крв за рано откривање на колоректален рак.`,
  114: `\n\nПРЕДИЗВИЦИ И НАДЕЖ. Ракот на панкреас има висок морталитет. Кај 80% од пациентите дијагнозата се поставува во напреднат стадиум. Ендоскопската ултрасонографија овозможува прецизна биопсија. КТ скенот со контраст ја проценува ресектабилноста. Неоадјувантната хемотерапија го зголемува процентот на успешни операции. FOLFIRINOX протоколот покажува најдобар одговор. Хируршката ресекција останува единствена куративна опција. Кај метастатска болест, хемотерапијата го продолжува преживувањето. Таргетираните терапии како ерлотиниб даваат скромна корист. Имунотерапијата е ефикасна само кај MSI-високи тумори. Генетското тестирање за BRCA мутации отвора опции за PARP инхибитори. Клиничките испитувања нудат нови надежни терапии. Раното откривање преку скрининг кај високоризични популации е во фаза на истражување.`,
  115: `\n\nРЕТКА БОЛЕСТ СО ПОСЕБНИ ПРЕДИЗВИЦИ. Ракот на дојка кај мажи сочинува помалку од 1% од сите случаи. Дијагнозата често се поставува подоцна поради недостаток на свест. Мажите треба да бидат свесни за промени во градната област. Симптомите вклучуваат безболна грутка, влекување на брадавицата и исцедок. BRCA2 мутациите се почести кај мажи со рак на дојка. Третманот следи слични принципи како кај жени. Мастектомијата е почеста од поштедната хирургија. Терапијата со тамоксифен е ефикасна. Генетското советување се препорачува за сите мажи со оваа дијагноза. Мажите со BRCA мутации имаат зголемен ризик и од рак на простата. Психолошката поддршка е важна поради стигмата и чувството на изолација. Групите за поддршка специфични за мажи се сè подостапни. Едукацијата на јавноста и здравствените работници го забрзува препознавањето и подобрува прогнозата.`,

  // Cat 6: Psihijatrija (116-120)
  116: `\n\nНОВИ ПРЕДИЗВИЦИ. Депресијата кај адолесценти е во пораст. Социјалните мрежи имаат значајно влијание врз менталното здравје. Постојаната споредба со другите и идеализирани слики создаваат нереални очекувања. Сајбер-малтретирањето е дополнителен фактор на ризик. Намалувањето на физичката активност и промената на спиењето влијаат на расположението. Скринингот за депресија кај адолесценти препорачуваат сите педијатриски насоки. Когнитивно-бихејвиоралната терапија е прва линија. Групната терапија им помага на младите да се поврзат. Семејната терапија го подобрува домашното опкружување. Антидепресивите кај адолесценти бараат внимателно следење. Селективните инхибитори на серотонин се најбезбедна опција. Родителите треба да знаат дека менталното здравје е исто толку важно како физичкото. Интервенирањето рано спречува хронична депресија во возрасниот период.`,
  117: `\n\nСОВРЕМЕНИ ТЕРАПИИ. ПТСН е сложено нарушување кое бара специјализиран третман. Когнитивно-бихејвиоралната терапија фокусирана на траума е најефикасна. ЕМДР терапијата користи билатерална стимулација за преработка на трауматски спомени. Пролонгираната експозиција помага во намалување на избегнувањето. Селективните инхибитори на серотонин се лекови на избор. Празосин е ефикасен за ноќни кошмари. Групната терапија со други преживеани од траума е поддршка. Семејната вклученост е важна за закрепнување. Телетерапијата го зголемува пристапот до третман за рурални средини. Ветераните се особено ранлива популација за ПТСН. Истражувањата за псилоцибин асистирана терапија покажуваат ветувачки резултати. Раната интервенција по трауматски настан го намалува развојот на ПТСН. Иднината носи персонализирани пристапи базирани на невробиолошки профили.`,
  118: `\n\nРАНА ДИЈАГНОЗА. Шизофренијата се манифестира во доцна адолесценција. Раните знаци вклучуваат социјална повлеченост и пад на функционирање. Позитивните симптоми како халуцинации и заблуди се драматични. Негативните симптоми како апатија и анхедонија се хронични. Когнитивниот дефицит влијае на меморија и внимание. МРИ на мозок исклучува органска причина. Антивоспалителните терапии се истражуваат како дополнителен третман. Антипсихотиците од прва и втора генерација се основа на третманот. Клозапинот е резервиран за резистентна шизофренија. Психосоцијалната рехабилитација го подобрува функционирањето. Поддржаното вработување помага во интеграција. Психоедукацијата на семејството го намалува ризикот од рецидив. Адхеренцијата кон терапија е најголем предизвик. Долго дејствувачките инјекции го олеснуваат третманот. Редовното следење на метаболичките параметри е неопходно поради несаканите ефекти на антипсихотиците.`,
  119: `\n\nЗГОЛЕМЕНА ЗАСТАПЕНОСТ. Анксиозните нарушувања се најчести ментални нарушувања. Пандемијата го зголеми нивото на анксиозност во популацијата. Генерализираното анксиозно нарушување вклучува постојана преокупација. Паничното нарушување се манифестира со ненадејни напади на страв. Социјалната анксиозност го отежнува секојдневното функционирање. Когнитивно-бихејвиоралната терапија е златен стандард. Техниките за свесност и релаксација се ефикасни. Селективните инхибитори на серотонин се прва линија на лекови. Бензодиазепините се краткорочно решение со ризик од зависност. Вежбите за дишење го намалуваат акутниот страв. Редовната физичка активност го намалува хроничниот стрес. Избегнувањето на кофеин и алкохол помага. Едукацијата за разбирање на одговорот на телото на страв го намалува стигматизирањето. Комбинацијата на терапија и лекови дава најдобри долгорочни резултати.`,
  120: `\n\nПРЕДИЗВИЦИ ВО СОВРЕМЕНОТО ОПШТЕСТВО. АДХД се дијагностицира и кај деца и кај возрасни. Возрасните со АДХД често остануваат недијагностицирани. Симптомите на невнимание дезорганизираат секојдневни активности. Хиперактивноста кај возрасни се манифестира како внатрешен немир. Импулсивноста влијае на финансиски одлуки и односи. Дијагнозата бара сеопфатна историја и скали за проценка. Коморбидитетите со депресија и анксиозност се чести. Медикацијата со стимуланси е високо ефикасна. Не-стимуланс опции постојат за одредени пациенти. Структурирани рутини и организациони стратегии помагаат. Когнитивно-бихејвиоралната терапија развива вештини за справување. Разбирањето на невробиологијата на АДХД го намалува стигматизирањето. Поддршката на работното место преку прилагодени работни обврски го подобрува професионалниот успех кај возрасните со АДХД. Третираниот АДХД не претставува попреченост туку различност во начинот на функционирање.`,

  // Cat 7: Stomatologija (121-125)
  121: `\n\nДИГИТАЛНА РЕВОЛУЦИЈА. Дигиталната стоматологија го менува начинот на лекување. ЦАД/ЦАМ технологијата овозможува изработка на коронки и мостави во една посета. Интраоралните скенери ги заменуваат традиционалните отпечатоци. Денталните импланти имитираат природни заби и спречуваат губење на коска. Секојдневното миење со паста со флуор ја зајакнува глеѓта. Конецот за заби ја чисти областа меѓу забите што четката не може да ја достигне. Редовните контроли на секои шест месеци се задолжителни. Проблемите се идентификуваат пред да станат сериозни. Нелекуваниот кариес доведува до инфекција и губење на забот. Едукацијата за орално здравје треба да започне на рана возраст. Флуоризацијата на водата го намалува кариесот за 25%. Новите материјали за пломбирање се поотпорни и естетски. Ласерската стоматологија овозможува безболен третман на кариес.`,
  122: `\n\nЕСТЕТСКИ ПРИСТАП. Естетската стоматологија го подобрува изгледот и самодовербата. Забелувањето на забите е привремена козметичка процедура. Фасетите од порцелан коригираат неправилности во боја и форма. Ортодонцијата веќе не е само за деца. Инвизигна и керамички брекети се дискретни опции. Контурите на непцата можат да се обликуваат со ласер. Нарушувањата на темпоромандибуларниот зглоб предизвикуваат болка во вилицата. Бруксизмот или стискањето на заби создава абразија. Ботоксот во масертер го намалува стискањето. Стоматолошкиот страв е чест и лечив. Седацијата и општа анестезија се опции за анксиозни пациенти. Брексизмот бара изработка на ноќна шина за заштита на забите. Козметичката стоматологија нуди решенија за широк спектар на естетски проблеми.`,
  123: `\n\nВРСКА СО ГЕНЕРАЛНОТО ЗДРАВЈЕ. Пародонтитисот го зголемува ризикот од срцеви заболувања. Бактериите од устата влегуваат во крвотокот и предизвикуваат воспаление. Дијабетесог создава двонасочна врска со пародонтитис. Контролата на гликемија го подобрува оралното здравје. Бремените жени со пародонтитис имаат зголемен ризик од предвремено породување. Редовните стоматолошки прегледи се безбедни во бременоста. Остеопорозата влијае на алвеоларната коска. Артритисот во темпоромандибуларниот зглоб предизвикува болка. Прехранбените навики како честа конзумација на кисели пијалаци создаваат ерозија на глеѓта. Врската помеѓу оралното и системското здравје е добро документирана. Стоматолозите се често првите што откриваат знаци на системски болести. Редовните стоматолошки прегледи може да откријат рани знаци на дијабетес, анемија и други состојби преку оралните манифестации.`,
  124: `\n\nСОВРЕМЕНА ОРТОДОНЦИЈА. Денталните импланти се златен стандард за замена на изгубени заби. Процедурата вклучува вградување титаниумски заврток во коската. Осеоинтеграцијата трае 3-6 месеци. Привремените коронки се поставуваат веднаш по имплантацијата. Конечната коронка се поставува по осеоинтеграција. Имплантите спречуваат губење на коска и одржуваат контура на лицето. Ризиците вклучуваат инфекција и неуспешна интеграција. Пушачите имаат поголем ризик од неуспех. Костените графтови може да бидат потребни ако коската е недоволна. Денталните импланти бараат иста орална хигиена како природните заби. За пациенти со дијабетес, добрата гликемиска контрола е предуслов за успешна имплантација. Имплант-поддржаните протези нудат стабилност за пациенти со целосна беззабост.`,
  125: `\n\nПРАВИЛНА НЕГА. Детската стоматологија се фокусира на превенција. Првата посета кај стоматолог треба да биде до 1 година возраст. Флуоридните лакови во ординација го намалуваат кариесот. Печатењето на фисури на катници превенира кариес. Млечните заби се важни за правилен развој на вилицата. Правењето место за трајните заби е една од нивните функции. Предвременото губење на млечни заби предизвикува проблеми. Навиките како цицање палец треба да се корегираат до 4 години. Исхраната богата со шеќер го зголемува ризикот од кариес. Соковите и млекото пред спиење се штетни за забите. Едукацијата за четкање и конец треба да биде забавна за децата. Наградите и системите за мотивација помагаат во градење навики. Детските стоматолози се специјализирани за работа со деца.`,

  // Cat 8: Farmacija (126-130)
  130: `\n\nНОВИ ТЕНДЕНЦИИ. Фармацевтската грижа го проширува опсегот на работа на фармацевтите. Фармацевтите администрираат вакцини во многу земји. Мерењето на крвен притисок и холестерол се дел од нивните услуги. Проверките на лекови и консултациите за хронични болести го подобруваат исходот. Аутоматизацијата во аптеките го зголемува времето за фармацевтска грижа. Е-рецептите се стандард во многу здравствени системи. Вештачката интелигенција помага во откривање интеракции на лекови. Носливите уреди и апликациите ја подобруваат адхеренцијата кон терапијата. Генетското тестирање во аптека станува реалност. Фармацевтите се најдостапните здравствени работници. Обуката за новите технологии е континуиран процес. Иднината носи интеграција на вештачка интелигенција во секојдневната фармацевтска пракса. Тригерот за профилирање на пациентот го подобрува исходот.`,

  // Cat 9: Ishrana (131-135)
  131: `\n\nМЕТАБОЛИЧКИ ЕФЕКТИ. Интервален пост е популарен тренд со научно поткрепени здравствени придобивки. Најчестите протоколи вклучуваат 16:8 пост (16 часа гладување, 8 часа јадење) и 5:2 диета (5 дена нормално јадење, 2 дена рестрикција). Студиите покажуваат дека интервалниот пост ја подобрува инсулинската чувствителност и го намалува воспалението. Нивоата на кетони во крвта се зголемуваат за време на постот, што промовира кетоза и согорување на масти. Инсулинските нивоа значително опаѓаат за време на постот. Грелинот, хормонот на глад, се зголемува но по период на адаптација се враќа во нормала. Храната со висок протеин и влакна го намалува чувството на глад за време на постот. Постот не е погоден за бремени жени, лица со дијабетес тип 1 или историја на нарушувања во исхраната. Консултацијата со нутриционист пред започнување интервален пост се препорачува. Долгорочните студии покажуваат дека интервалниот пост може да го продолжи животниот век преку активирање на процесите на автофагија. Комбинацијата со медитеранска исхрана дава дополнителни кардиоваскуларни придобивки. Важно е да се одржува хидратација за време на постот.`,
  132: `\n\nХРАНА И РАСПОЛОЖЕНИЕ. Врската помеѓу исхраната и менталното здравје е сè поистражувана. Гастроинтестиналниот систем се нарекува втор мозок поради сложената врска преку вагусниот нерв. Серотонинот, невротрансмитерот на среќа, се произведува 90% во цревата. Пробиотската храна како јогурт, кефир и кисела зелка го подобрува цревниот микробиом. Омега-3 масните киселини од риба и ленено семе го намалуваат воспалението во мозокот. Витамините од Б група се вклучени во синтезата на невротрансмитери. Антиоксидансите од бобинки и темно чоколадо ги штитат нервните клетки. Високата потрошувачка на шеќер и ултра-преработена храна е поврзана со зголемен ризик од депресија. Избегнувањето на вештачки засладувачи исто така помага. Ферментираната храна содржи корисни бактерии. Редовното конзумирање на ферментирани млечни производи е поврзано со пониски нивоа на стрес. Исхраната во стил на медитеранска диета е поврзана со најнизок ризик од ментални нарушувања.`,
  133: `\n\nСОВРЕМЕНИ ПРИСТАПИ. Исхраната базирана на растенија добива на популарност. Вегетаријанската и веганската исхрана се поврзани со понизок ризик од хронични болести. Внимателното планирање обезбедува внес на сите потребни нутриенти. Витаминот Б12 бара суплементација кај веганите. Железото од растителни извори има помала биорасположивост. Комбинацијата со витамин Ц од цитрус го зголемува апсорпцијата. Калциумот се добива од збогатени млечни алтернативи. Зелениот лиснат зеленчук е богат со калциум и магнезиум. Протеините од грашок, соја и киноа се комплетни. Исхраната базирана на растенија го намалува јаглеродниот отпечаток. Спортистите на растителна исхрана покажуваат одлични перформанси. Популарноста продолжува да расте, со сè повеќе ресторани кои нудат опции. Транзицијата треба да биде постепена за да се овозможи адаптација на дигестивниот систем.`,
  134: `\n\nБЕЗБЕДНОСТ И ЕФИКАСНОСТ. Суплементите се популарни но нивната употреба бара претпазливост. Витамин Д, омега-3, пробиотици и магнезиум се меѓу најкористените суплементи. Витамин Д го поддржува имунитетот и здравјето на коските. Дозите над 4000 ИУ дневно носат ризик од токсичност. Омега-3 суплементите го намалуваат воспалението и триглицеридите. Рибиното масло од сардини и аншоа е најквалитетно. Пробиотиците ја подобруваат цревната флора. Различни соеви на пробиотици имаат различни ефекти. Магнезиумот помага при мускулни грчеви, мигрена и запек. Сите суплементи не се регулирани како лекови. Трети лица сертификати како USP и NSF обезбедуваат квалитет. Природно не значи безбедно. Повеќе не значи подобро. Суплементите треба да дополнуваат, не да заменуваат урамнотежена исхрана. Консултацијата со лекар пред употреба е задолжителна.`,
  135: `\n\nЗДРАВЈЕ НА ЦРЕВАТА. Цревниот микробиом влијае на целокупното здравје. Секој човек има уникатен состав на цревни бактерии. Диверзитетот на микробиомот е поврзан со подобро здравје. Храната богата со влакна како зеленчук, овошје и интегрални жита го храни микробиомот. Пребиотиците се храна за корисните бактерии во цревата. Цикоријата, кромидот и лукот се богати со пребиотици. Антибиотиците го нарушуваат микробиомот, често за месеци. Пробиотиците по антибиотска терапија помагаат во обновување. Дисбиозата на цревниот микробиом е поврзана со дебелина, дијабетес и алергии. Воспалителните болести на цревата се поврзани со нарушен микробиом. Истражувањата за фекална трансплантација покажуваат успех кај Clostridium difficile инфекција. Антиинфламаторната диета го намалува воспалението во цревата. Иднината носи персонализирана исхрана базирана на анализа на микробиомот.`,

  // Cat 10: Medicinski tehnologii (136-140)
  136: `\n\nПРИМЕНА ВО МЕДИЦИНАТА. Вештачката интелигенција го трансформира медицинското сликање. Алгоритмите за длабоко учење анализираат радиолошки слики со висока точност. Во дерматологијата, ВИ детектира малигни промени на кожата. Патологијата користи ВИ за анализа на хистолошки препарати. ЕКГ интерпретацијата со ВИ ја идентификува атријалната фибрилација. Офталмологијата користи ВИ за скрининг на дијабетична ретинопатија. Етичките прашања вклучуваат одговорност за грешки и заштита на податоци. ВИ не ги заменува лекарите, туку ги поддржува во донесување одлуки. Транспарентноста на ВИ системите е од клучно значење. Пристрасноста во алгоритмите поради нерепрезентативни податоци е познат проблем. Регулативата за ВИ во медицината се развива. Потребна е едукација на здравствените работници за работа со ВИ. Иднината носи ВИ асистирана дијагноза во реално време за време на операции и процедури.`,
  137: `\n\nДИГИТАЛНА РЕВОЛУЦИЈА. Носливите уреди го следат здравјето во реално време. Паметните часовници мерат отчукувања на срцето, кислород и ЕКГ. Глукозните монитори во реално време го менуваат третманот на дијабетес. Паметните ваги следат состав на телото и хидратација. Уредите за крвен притисок овозможуваат домашно следење. Предиктивната анализа ги идентификува раните знаци на влошување. Интеграцијата со електронски здравствени записи овозможува сеопфатна слика. Приватноста на податоците е главна грижа. Безбедноста на податоците и спречувањето на хакирање е приоритет. Точноста на потрошувачките уреди варира. Клиничката валидација е неопходна пред медицинска употреба. Податоците од носливите уреди помагаат во истражувања. Иднината носи сензори вградени во облека за континуиран мониторинг.`,
  138: `\n\nПРЕДИЗВИЦИ И ПЕРСПЕКТИВИ. Електронските здравствени записи ја подобруваат координацијата на грижата. Интероперабилноста помеѓу различни системи останува предизвик. HL7 FHIR протоколот овозможува размена на податоци. Дуплирањето на тестови се намалува со интегриран систем. Безбедноста на здравствените податоци е регулирана со HIPAA и GDPR. Телемедицината користи шифрирани видео консултации. Пациентите имаат пристап до сопствените здравствени податоци преку портали. Вештачката интелигенција помага во анализа на големи податоци. Облак технологиите обезбедуваат скалабилност и пристапност. Резервните копии и плановите за обновување се неопходни за континуитет. Сајбер-нападите на здравствени институции се зголемуваат. Едукацијата на персоналот за сајбер-безбедност е задолжителна. Иднината носи блокчејн технологии за безбедно споделување на здравствени податоци.`,
  139: `\n\nХИРУРШКА ПРЕЦИЗНОСТ. Роботиката во хирургијата овозможува минимално инвазивни процедури. Да Винчи системот е најпознат хируршки робот. Хирургот контролира од конзола со 3Д визија. Треморот на раката се филтрира за поголема прецизност. Роботската хирургија овозможува пократок опоравок за пациентите. Губењето на крв е намалено, а болничкиот престој пократок. 3Д печатењето создава персонализирани импланти за пациенти. Хируршките водичи за сложени операции се 3Д печатени. Сложените фрактури на карлица може да се планираат со 3Д модели. Образованието на хирурзите вклучува симулатори. Трошоците за роботски системи се високи, но се намалуваат. Предностите вклучуваат помала болка, побрзо закрепнување и подобра естетика. Иднината носи автономни роботски системи за специфични задачи.`,
  140: `\n\nТОЧНОСТ И ДОСТАПНОСТ. Новите дијагностички технологии го забрзуваат откривањето на болести. Тестовите на крв за рано откривање на рак откриваат циркулирачка туморска ДНК. Нанопор секвенционирањето овозможува брзо и евтино генетско тестирање. Брзите тестови за заразни болести даваат резултат за неколку минути. Латералните проточни тестови се познати од пандемијата. Технологиите на CRISPR се користат за високоспецифична дијагностика. Компјутеризираната томографија со ниска доза го намалува зрачењето. Ултразвукот со портативни уреди станува достапен и надвор од болници. Еластографијата ја проценува цврстината на ткивото. Електронскиот нос открива болести преку мирис на здив. МикроРНА анализата открива рани знаци на болести како рак и срцеви заболувања. Иднината носи мултиплекс тестови за повеќе биомаркери истовремено. Интеграцијата на вештачка интелигенција ги прави дијагностичките алатки попрецизни и подостапни за рутинска употреба.`,

  // Cat 11: Infektivni bolesti (141-145)
  141: `\n\nПРЕВЕНЦИЈА И КОНТРОЛА. Антимикробната резистенција е глобална закана. Бактериите развиваат механизми за резистенција на сите познати антибиотици. Грамотрицативните бактерии се особено проблематични. Колистинот е последна линија на одбрана. Новите антибиотици се во развој, но процесот е бавен. Бета-лактамаза инхибиторите обновуваат ефикасност на стари антибиотици. Плазмидите пренесуваат резистенција помеѓу бактерии. Степенот на инфекции со мулти-резистентни бактерии расте. Болничките инфекции се често резистентни. Рационалното препишување го забавува развојот на резистенција. Антимикробниот stewardship во болници е задолжителен. Потребни се нови класи антибиотици за да останеме чекор понапред. Истражувачките молекули во различни фази на клинички испитувања може да донесат нови опции во наредните години. Цревната флора игра важна улога во превенцијата од резистентни бактерии.`,
  142: `\n\nНОВИ ПРЕДИЗВИЦИ. МПОКС (поранешно мајмунски сипаници) предизвика глобална епидемија во 2022. Вирусот се пренесува преку близок контакт со лезии. Симптомите вклучуваат треска, главоболка и карактеристичен осип. Лимфните јазли се зголемени. Дијагнозата се потврдува со ПЦР. Повеќето случаи се самоограничувачки и благи. Антивирални лекови како тековиримат се користат за тешки случаи. Вакцината против сипаници обезбедува крстосан имунитет. Пост-експозициска вакцинација е ефикасна. Ризичните групи вклучуваат здравствени работници. Едукацијата за начини на пренос го намалува ширењето. Стигмата околу МПОКС може да го попречи пријавувањето и лекувањето. СЗО препорачува глобална подготвеност за идни епидемии. Ефикасниот надзор и раното откривање се клучни за контрола на ширењето.`,
  143: `\n\nГЛОБАЛНА ПЕРСПЕКТИВА. Вирусот на Западен Нил се шири во нови региони. Комарците од видот Culex се главен вектор. Птиците се природен резервоар на вирусот. Луѓето се случајни домаќини. Повеќето инфекции се асимптоматски. Кај некои пациенти се развива треска, главоболка и осип. Невроинвазивната форма предизвикува менингитис и енцефалитис. Постарите лица се под зголемен ризик. Дијагнозата се поставува со серологија или ПЦР. Нема специфичен антивирусен третман. Климатските промени ја прошируваат зоната на комарци. Заштитата од комарци со репеленти е превентивна мерка. Намалувањето на стоечка вода околу домовите го намалува размножувањето на комарците. Програмите за мониторинг на комарци и птици обезбедуваат рано предупредување за потенцијални епидемии.`,
  144: `\n\nЗГОЛЕМЕНА ЗАСТАПЕНОСТ. Лајмската болест се шири во нови географски области поради климатските промени. Крлежите од видот Ixodes се главен вектор. Карактеристичниот осип во форма на биково око е патогномоничен. Раната дијагноза со серологија и клиничка слика е важна. Доксициклинот е третман на избор за рана Лајмска болест. Доцната Лајмска болест вклучува артритис, невролошки и срцеви компликации. Долготрајните симптоми по третман се контроверзни. Заштитата од крлежи вклучува облека со долги ракави и репеленти. Проверката на телото по престој во природа е задолжителна. Крлежот треба да се отстрани со пинцета. Периодот на пренос на бактерии од крлеж е 24-48 часа. Климатските промени го продолжуваат сезоната на крлежи и го шират нивниот опсег. Едукацијата на јавноста за превенција е клучна. Истражувањата за вакцина против Лајмска болест се во напредна фаза.`,
  145: `\n\nДИЈАГНОЗА И ТРЕТМАН. Туберкулозата останува една од најсмртоносните инфективни болести. Латентиот облик (LTBI) опфаќа една четвртина од светската популација. Активната туберкулоза се манифестира со кашлица, треска и губење на тежина. Имунолошките тестови како IGRA и Манту се користат за скрининг. Микроскопијата на спутум е брза дијагностичка метода. PCR тестовите го детектираат Mycobacterium tuberculosis. Секвенционирањето открива профили на резистенција. Лечењето на латентна ТБ спречува активација на болеста. Стандардниот 6-месечен режим на антибиотици е ефикасен. Мулти-резистентната туберкулоза бара подолг и посложен третман. Адхеренцијата кон терапијата е критична за успешен исход. Нов вакцина со поголема ефикасност од БЦГ е во клинички испитувања. Глобалните напори за елиминација на туберкулозата до 2030 се амбициозни.`,

  // Cat 12: Medicina na trud (146-150)
  146: `\n\nЗАШТИТА НА ЗДРАВЈЕТО. Професионалните болести се превентибилни преку систематски мерки. Пневмокониозата кај рудари и градежни работници се спречува со заштита на дишните патишта. Силикозата од вдишување на силициум кристали е нелечива. Превенцијата вклучува контрола на прашина и вентилација. Респираторите со висок филтрационен капацитет се задолжителни во ризични средини. Редовниот медицински преглед со спирометрија го следи здравјето на белите дробови. Ултравучните прегледи овозможуваат откривање на промени. Работодавателот е должен да обезбеди безбедна работна средина. Губењето на слух од бучава е најчеста професионална болест. Заштитните чепчиња за уши и антифони се задолжителни. Изложеноста на бучава над 85 децибели бара заштита. Аудиометријата се препорачува годишно за работници изложени на бучава. Ергономските мерки ги спречуваат мускулно-скелетните нарушувања. Програмите за заштита на здравјето при работа се исплатливи преку намален absentизам и зголемена продуктивност.`,
  147: `\n\nПРАВНА РЕГУЛАТИВА. Менталното здравје на работното место станува приоритет. Стресот на работа е водечка причина за отсутност. Намалувањето на работното време и флексибилните работни аранжмани го намалуваат стресот. Програмите за ментално здравје на работното место се зголемуваат. Психосоцијалните ризици вклучуваат прекумерно оптоварување, малтретирање и недостаток на контрола. Изгорувањето или бурн-аут е признат синдром. Препознавањето на симптомите на изгорување кај вработените е одговорност на работодавачот. Интервенциите за намалување на стрес вклучуваат обуки за справување и советување. Проценката на психосоцијални ризици е задолжителна во многу земји. Работните места со висока побарувачка и ниска контрола се најстресни. Онлајн ресурсите за ментално здравје се сè подостапни за вработените. Грижата за менталното здравје на вработените ја зголемува продуктивноста и задржувањето на таленти. Медицинските професионалци се особено изложени на ризик од изгорување.`,
  148: `\n\nЕРГОНОМСКИ ПРИСТАП. Ергономијата спречува мускулно-скелетни нарушувања поврзани со работа. Канцелариските работници се изложени на ризик од синдром на карпален тунел. Правилното држење на телото при компјутерска работа е клучно. Мониторот треба да биде на висина на очите. Столот треба да поддржува лумбална 'рбетница. Паузите на секој час со истегнување се препорачуваат. Работниците во физичка работа имаат ризик од повреди на грбот. Техниките за правилно кревање тегови се задолжителна обука. Адаптивната опрема на работното место ја намалува повредата. Ергономската проценка на работното место треба да се спроведува редовно. Раните интервенции при мускулно-скелетна болка спречуваат хронифицирање. Физикалната терапија на работно место го намалува отсутноста. Враќањето на работа по повреда треба да биде постепено со прилагодени задачи. Трошоците за ергономски прилагодувања се повеќекратно исплатливи.`,
  149: `\n\nИМПЛЕМЕНТАЦИЈА. Безбедносните протоколи на работно место штитат од професионални ризици. Проценката на ризик за секое работно место е задолжителна. Контролните хиерархии вклучуваат елиминација, замена, инженерски контроли и лична заштитна опрема. Обуката за безбедност на работниците се спроведува редовно. Хемиските агенси бараат безбедносни листови со податоци. Ракувањето со опасни материи бара посебна обука. Биолошките агенси се ризик во здравствени установи. Изложеноста на јонизирачко зрачење се следи со дозиметри. Работодавателите се законски обврзани да обезбедат безбедна работна средина. Инспекциите на трудот ги проверуваат условите на работните места. Пријавувањето на несреќи и професионални болести е законска обврска. Учеството на работниците во безбедносни комитети го подобрува спроведувањето. Безбедносната култура на работното место се гради преку лидерство и ангажираност.`,
  150: `\n\nФИЗИЧКИ И ПСИХОСОЦИЈАЛНИ ФАКТОРИ. Седентарниот начин на работа претставува здравствен ризик. Долготрајното седење е поврзано со зголемен ризик од кардиоваскуларни болести. Стоечките работни станици го намалуваат времето поминато седејќи. Тркалезните бироа за одење овозможуваат движење за време на работа. Интензитетот на физичката активност на работното место може да се зголеми преку активни паузи. Кратките прошетки на секој час го намалуваат ризикот од тромбоза. Работниците кои стојат долго имаат ризик од венска инсуфициенција. Алтернацијата помеѓу седење и стоење е оптимална. Работодавателите треба да обезбедат простории за релаксација и пауза. Промоцијата на физичка активност на работното место преку фитнес програми го подобрува здравјето на вработените. Хидратацијата на работното место е често занемаруван аспект. Здравата исхрана преку обезбедување овошје на работното место придонесува за целокупното здравје на вработените.`,

  // Cat 13: Imunologija (151-155)
  151: `\n\nИНДИВИДУАЛИЗИРАН ПРИСТАП. Автоимуните болести претставуваат хетерогена група на нарушувања. Имуниот систем погрешно ги напаѓа сопствените ткива. Реуматоидниот артритис ги зафаќа зглобовите. Системскиот лупус еритематозус зафаќа повеќе органи. Дијагнозата се поставува со клинички критериуми и лабораториски тестови. Антинуклеарните антитела се маркер за повеќе автоимуни болести. Биолошките лекови го трансформираа третманот. TNF инхибиторите се користат за реуматоиден артритис и псоријаза. JAK инхибиторите се орална алтернатива на биолошките лекови. Коморбидитетите како кардиоваскуларни заболувања се чести. Редовното следење и прилагодување на терапијата е од суштинско значење. Новите терапии се насочени кон специфични имуни патишта. Иднината носи персонализирана имунотерапија базирана на генетски профил на секој пациент. Раното откривање на автоимуни болести спречува неповратно оштетување на органите.`,
  152: `\n\nМЕХАНИЗМИ АКЦИЈА. Имунолошкиот систем се состои од вроден и адаптивен имунитет. Вродениот имунитет е прва линија на одбрана. Природните клетки убијки уништуваат заразени клетки. Макрофагите фагоцитираат патогени. Дендритичните клетки презентираат антигени на Т-клетките. Адаптивниот имунитет обезбедува долгорочна меморија. Б-клетките произведуваат антитела. Т-клетките уништуваат заразени клетки. Имуноглобулинот Е (IgE) е вклучен во алергиски реакции. Цитокините се сигнални молекули кои ја регулираат имуната реакција. Разбирањето на механизмите води до нови терапии. Провоспалителните цитокини како IL-6 и TNF се цели за биолошки лекови. Регулаторните Т-клетки играат клучна улога во имунолошката толеранција. Автоимуниот одговор се регулира преку комплексни механизми на контрола и рамнотежа помеѓу ефекторни и регулаторни клетки.`,
  153: `\n\nТИПОВИ И ТРЕТМАН. Примарните имунодефициенции се генетски нарушувања. Бројни примарни имунодефициенции се идентификувани. Заедничката варијабилна имунодефициенција е најчеста кај возрасни. Х-поврзаната агамаглобулинемија се манифестира во раното детство. Тешките комбинирани имунодефициенции бараат трансплантација на коскена срцевина. Новите генски терапии нудат потенцијално лекување. Скринингот на новороденчиња за тешки имунодефициенции е достапен. Редовната инфузија на имуноглобулин ги штити пациентите од инфекции. Антибиотската профилакса е задолжителна за спречување на инфекции. Ракот е зголемен ризик кај имунодефициентни пациенти. Здравствениот систем мора да обезбеди специјализирана грижа за овие ретки болести. Родителите треба да бидат едуцирани за препознавање на инфекции кај децата со имунодефициенција. Напредокот во молекуларната генетика овозможува прецизна дијагноза на сè повеќе примарни имунодефициенции.`,
  154: `\n\nПЕРСОНАЛИЗИРАНА ИМУНОТЕРАПИЈА. Биолошките лекови се револуционерен пристап за автоимуни болести. Исхраната и животниот стил го модулираат имуниот систем. Витаминот Д игра клучна улога во имуната регулација. Недостатокот на витамин Д е поврзан со автоимуни болести. Омега-3 масните киселини го намалуваат воспалението. Пробиотиците го поддржуваат цревниот имунитет. Медитеранската диета има антиинфламаторни ефекти. Физичката активност го модулира имунитетот преку цитокини. Стресот го потиснува имуниот систем. Хроничниот стрес е фактор за автоимуност. Алергиската имунотерапија ја менува природната историја на алергии. Имунотерапијата за рак го активира имуниот систем против туморот. Имунолошката толеранција е цел на терапиите за автоимуни болести. Новите технологии овозможуваат персонализирана имунотерапија базирана на специфичниот имунолошки профил на пациентот.`,
  155: `\n\nНОВИ ХОРИЗОНТИ. Воспалението е заеднички именител на многу хронични болести. Акутното воспаление е заштитен одговор на телото. Хроничното воспаление е штетно и доведува до ткивно оштетување. Кардиоваскуларните болести, дијабетесот и ракот се поврзани со хронично воспаление. Цитокините како TNF и IL-6 се главни медијатори на воспаление. CRP е биомаркер за системско воспаление. Антиинфламаторната диета богата со антиоксиданси го намалува воспалението. Физичката активност има антиинфламаторни ефекти. Хроничниот стрес го зголемува воспалението преку кортизол. Спиењето од 7-9 часа го регулира инфламаторниот одговор. Медитеранската диета е најпроучувана за антиинфламаторни ефекти. Новите биомаркери на воспаление овозможуваат рана детекција и мониторинг. Терапиите насочени кон хронично воспаление го намалуваат ризикот од повеќе хронични болести. Иднината носи антиинфламаторни стратегии за превенција на мултиморбидитет.`,

  // Cat 14: Endokrinologija (156-160)
  156: `\n\nДИЈАГНОЗА И ТРЕТМАН. Тироидната жлезда регулира метаболизам и енергија. Автоимуниот тироидитис (Хашимото) е најчеста причина за хипотироидизам. Заморот, чувствителност на студ, запек и сува кожа се главни симптоми. Лабораториските тестови откриваат зголемен TSH и намалени слободни T3 и T4. Антитироидните антитела ја потврдуваат автоимуната основа. Замената со левотироксин е ефикасен и безбеден третман. Дозирањето се прилагодува според нивото на TSH. Гравесовата болест предизвикува хипертироидизам со губење на тежина и тахикардија. Радиоактивниот јод е дефинитивен третман. Тироидектомијата се користи кај голема гушавост. Редовното следење на тироидните хормони е неопходно. Бремените жени треба да одржуваат нормална тироидна функција. Скринингот на новороденчиња за вроден хипотироидизам спречува ментална ретардација. Нодулите на тироидната жлезда се чести и бараат ехосонографско следење. Третманот со левотироксин треба да се зема на празен стомак за оптимална апсорпција.`,
  157: `\n\nМЕТАБОЛИЧКИ СИНДРОМ. Дебелината се дефинира со БМИ над 30. Висцералната маст е најопасна, се акумулира околу органите. Адипоцитите произведуваат инфламаторни цитокини. Лептинот е хормон за ситост што е резистентен кај дебели. Инсулинската резистенција е последица на хронично воспаление. Метаболичкиот синдром вклучува три или повеќе фактори: абдоминална дебелина, високи триглицериди, низок ХДЛ, висок крвен притисок и високо шеќер. Губењето на 5-10% од телесната тежина го подобрува метаболичкото здравје. Хируршките опции како гастричен бајпас се најефикасни за морбидна дебелина. Новите GLP-1 агонисти како семаглутид овозможуваат значително губење на тежината. Комбинацијата на медикаменти со промена на животниот стил дава најдобри резултати. Бихејвиоралната терапија помага за долгорочно одржување на тежината. Превенцијата на дебелина кај деца е најважната стратегија. Иднината носи нови комбинации на лекови и персонализиран пристап.`,
  158: `\n\nХОРМОНСКИ НАРУШУВАЊА. Синдромот на полицистични јајници (ПЦОС) зафаќа 10% од жените. Хиперандрогенизмот предизвикува акни, хирзутизам и опаѓање на коса. Ановулацијата доведува до нередовен менструален циклус и неплодност. Инсулинската резистенција е честа кај ПЦОС. Дијагнозата се поставува со Ротердамските критериуми. Ултразвукот покажува полицистични јајници. Контрацептивните таблети го регулираат циклусот и го намалуваат вишокот андрогени. Метформинот ја подобрува инсулинската чувствителност. Кломифен цитратот е прва линија за индукција на овулација. Губењето на тежина од 5% го обновува овулаторниот циклус. In vitro фертилизацијата нуди решенија за неплодност поврзана со ПЦОС. Долгорочните ризици вклучуваат дијабетес тип 2 и кардиоваскуларни болести. Редовното следење и скрининг за коморбидитети се неопходни за сеопфатна грижа за жените со ПЦОС.`,
  159: `\n\nДИЈАГНОЗА И ТРЕТМАН. Остеопорозата е тивка болест која напредува без симптоми. Фрактурите на колк, пршлени и рачен зглоб се први знаци. Дензитометријата (DXA) го мери коскениот минерален густина. Т-скорот под -2.5 укажува на остеопороза. Рангирањето на фрактурен ризик со FRAX алатката ја води терапијата. Калциумот од исхрана или суплементи е основа за здрави коски. Витаминот Д овозможува апсорпција на калциум. Дозирањето од 800-1000 ИУ дневно се препорачува за постари. Бисфосфонатите се прва линија на фармаколошки третман. Деносумаб е алтернатива за пациенти кои не поднесуваат бисфосфонати. Анаболните агенси како терипаратид го стимулираат создавањето на коска. Вежбите со тежина и отпор го зајакнуваат скелетот. Превенцијата започнува во детството со доволно калциум и физичка активност. Редовното тестирање на коскената густина се препорачува за жени во менопауза.`,
  160: `\n\nДИЈАГНОЗА И МЕНАЏМЕНТ. Синдромот на Кушинг предизвикува карактеристичен изглед. Хиперкортизолизмот доведува до централна дебелина и заоблено лице. Тип 2 дијабетес е најчест облик, поврзан со дебелина. Инсулинската резистенција е главниот механизам. Метформинот е прва линија на терапија. Инхибиторите на SGLT2 го намалуваат кардиоваскуларниот ризик. GLP-1 агонистите помагаат и во губење на тежина. Контролата на гликемија се следи со HbA1c на секои 3 месеци. Континуираното мерење на гликоза со сензори го подобрува управувањето. Редовниот скрининг за компликации е задолжителен. Скринингот за ретинопатија, невропатија и нефропатија е дел од рутинското следење. Едукацијата за самогрижа и пребројување јаглехидрати е суштинска за добар исход. Иднината носи автоматизирана инсулинска пумпа и вештачки панкреас за пациенти со дијабетес тип 1. Дијабетесот тип 2 може да се врати со значително губење на тежина и метаболичка хирургија.`,

  // Cat 15: Fitnes i prevencija (161-165)
  161: `\n\nФИЗИОЛОШКИ ПРИДОБИВКИ. Редовниот кардио тренинг го намалува ризикот од срцев удар и мозочен удар. Аеробниот тренинг го подобрува капацитетот на белите дробови и срцето. Високоинтензивниот интервален тренинг (HIIT) дава резултати за кратко време. Кратките интервали од 30 секунди со максимален напор ја подобруваат кардиоваскуларната кондиција. Пливањето е тренинг за цело тело со низок ризик од повреда. Трчањето го зајакнува кардиоваскуларниот систем и го намалува стресот. Тренингот со тежина одржува и гради мускулна маса. Повеќе мускулна маса значи повисок базален метаболизам. Функционалниот тренинг имитира секојдневни движења. Редовното вежбање го подобрува расположението и спиењето. Ендорфините ослободени за време на вежбање создаваат чувство на еуфорија. Сите форми на вежбање треба да вклучуваат загревање и истегнување. Комбинацијата на кардио и тренинг со тежина дава оптимални здравствени резултати. Консултацијата со фитнес професионалец пред започнување нов режим на вежбање се препорачува.`,
  162: `\n\nТЕХНИКИ И ПРИДОБИВКИ. Вежбите за флексибилност и истегнување го подобруваат опсегот на движење. Динамичкото истегнување пред вежбање подготвува мускули. Статичкото истегнување после вежбање го намалува заморот. Јогата комбинира истегнување, сила и медитација. Позите на јога ги зајакнуваат длабоките мускули. Пилатесот се фокусира на јадрото и 'рбетницата. Вдишувањето и издишувањето синхронизирано со движење го подобрува ефектот. Мускулно-скелетните повреди од вежбање вклучуваат истегнувања и руптури. Користењето правилна техника е најважна превенција од повреда. Одморот и опоравокот се подеднакво важни како и тренингот. Водата и електролитите се неопходни за хидратација за време на вежбање. Протеините после тренинг помагаат во обновување на мускулите. Флексибилноста се намалува со возраста, но редовното истегнување го забавува овој процес. Конзистентноста и трпението се клучот за долгорочни резултати во фитнесот.`,
  163: `\n\nПРАВИЛНА ИСХРАНА. Исхраната за фитнес и спорт бара баланс на макронутриенти. Јаглехидратите се главен извор на енергија за вежбање. Интегралните жита и овошјето обезбедуваат бавно ослободување на енергија. Внесот на протеини е потребен за обновување и раст на мускули. Препорачаниот внес за спортисти е 1.6-2.2 g/kg телесна тежина. Исушените јајца, пилешки гради, риба, тофу и леќа се одлични извори. Мастите се неопходни за хормонална функција. Хидратацијата пред, за време и после вежбање е критична. Темпото на потење и времетраењето на тренингот го одредуваат потребниот внес течности. Енергетските пијалаци не се потребни за повеќето луѓе. Планот за исхрана треба да биде индивидуализиран. Консултацијата со спортски нутриционист се препорачува за сериозни спортисти. Времето на внес на хранливи материи во однос на тренингот го оптимизира резултатот. Одморот и спиењето се една од најважните компоненти на фитнесот.`,
  164: `\n\nДИЗАЈН НА ПРОГРАМА. Тренингот со тежина гради мускулна маса и јачина. Прогресивното оптоварување е клуч за раст на мускули. Бројот на серии и повторувања зависи од целите: сила (3-6 повторувања), хипертрофија (8-12 повторувања) и издржливост (15-20 повторувања). Компаунд вежбите како склекови, чучњеви и мртво кревање ангажираат повеќе мускулни групи. Изолационите вежби се насочени кон еден мускул. Правилната форма е поважна од тежината. Прогресијата треба да биде бавна и конзистентна. Периодизацијата го менува интензитетот во текот на времето. Редовното вежбање го спречува остеопорозата. Тренингот на отпор го зголемува коскениот минерален густина. Напредокот се мери преку забележани тежини, репови и серии. Професионалниот тренер обезбедува соодветна програма и техника. Сослушувањето на телото и одморот се подеднакво важни како тренингот. Иднината носи персонализирани фитнес програми базирани на генетски профил.`,
  165: `\n\nПРАКТИЧНИ СТРАТЕГИИ. Редовниот сон од 7-9 часа е неопходен за здравје. Хигиената на спиење вклучува одржување на редовен распоред и темна просторија. Екраните треба да се избегнуваат најмалку еден час пред спиење. Сината светлина од уреди го потиснува мелатонинот. Матрасот и перницата треба да бидат соодветни за држењето на телото. Спиењето го зајакнува имунитетот и го намалува воспалението. Часовникот на телото или циркадијалниот ритам го регулира сонот. Истото време на будење секој ден го стабилизира внатрешниот часовник. Изложеноста на дневна светлина наутро го синхронизира циркадијалниот ритам. Кофеинот треба да се избегнува 6 часа пред спиење. Редовното вежбање го подобрува квалитетот на сонот. Дневните кратки дремки се корисни но подолги дремки го нарушуваат ноќниот сон. Техниките за релаксација како длабоко дишење и прогресивна мускулна релаксација го подобруваат заспивањето. Консултацијата сомнолог за хронична несоница е препорачлива.`,

  // Cat 16: Genetika (166-170)
  166: `\n\nТЕХНОЛОГИЈА И ПРИМЕНА. CRISPR технологијата овозможува прецизно уредување на гени. CRISPR-Cas9 системот користи РНК водич за таргетирање на специфична ДНК секвенца. Cas9 ензимот пресекува ДНК на саканото место. Клеточните механизми за поправка на ДНК се користат за вметнување или бришење гени. Потенцијалот за лекување на генетски болести е огромен. Српестата анемија и бета-таласемијата се успешно третирани во клинички испитувања. Испитувањата за третман на мускулна дистрофија и хемофилија се во тек. Етичките прашања вклучуваат уредување на герминативни клетки што може да се наследи. Мораториумот за наследно уредување на гени е широко поддржан. Пристапноста на CRISPR терапиите е ограничена поради високи трошоци. Регулативата за CRISPR терапии се развива постепено. Иднината носи уште попрецизни методи за уредување на гени со помалку несакани ефекти. База уредувањето и прим уредувањето се нови техники кои овозможуваат уште попрецизни генетски модификации.`,
  167: `\n\nЕТИЧКИ ПРАШАЊА. Генетското тестирање дава информации за ризик од болести. Директно-потрошувачкото генетско тестирање е популарно но ограничено. BRCA тестирањето за рак на дојка и јајчник има клиничка вредност. Враќањето на неочекувани наоди претставува етички дилеми. Генетското советување пред и после тестирање е задолжително. Варијантите со непознато значење создаваат неизвесност. Разликата помеѓу ризик и дијагноза не е секогаш јасна. Лажно позитивните резултати создаваат непотребна анксиозност. Лажно негативните резултати даваат лажна сигурност. Генетската дискриминација од осигурителни компании и работодавачи е забранета во многу земји. Приватноста на генетските податоци бара посебна заштита. Генетското тестирање на деца за болести со доцна манифестација е контроверзно. Меѓународните насоки препорачуваат внимателен пристап кон генетското тестирање и јасна комуникација на ризиците и придобивките.`,
  168: `\n\nПЕРСОНАЛИЗИРАНА МЕДИЦИНА. Фармакогенетиката објаснува зошто лекови дејствуваат различно кај луѓе. Генетските варијации во CYP450 ензимите влијаат на метаболизмот на лекови. Тестирањето пред третман со одредени лекови спречува несакани реакции. Абакавирот бара HLA-B*5701 тестирање пред употреба. Варфаринот има генетски базирани дозирачки алгоритми. Клопидогрелот бара активација преку CYP2C19. Генетските профили на туморот ги насочуваат онколошките терапии. EGFR мутациите одредуваат одговор на тирозин киназа инхибитори. Интеграцијата на генетските податоци во клиничката пракса е постепена. Едукацијата на лекарите за фармакогенетика е неопходна. Базите на податоци за генетско-фармаколошки асоцијации постојано растат. Иднината носи рутинско генетско тестирање пред препишување на многу лекови, што ќе ја зголеми ефикасноста и безбедноста на терапијата.`,
  169: `\n\nНОВИ ХОРИЗОНТИ. Епигенетиката проучува како околината влијае на генската експресија. ДНК метилацијата е еден од епигенетските механизми. Стресот, исхраната и токсините предизвикуваат епигенетски промени. Епигенетските промени се потенцијално реверзибилни. Истите близнаци со идентична ДНК можат да имаат различни епигенетски профили. Хроничниот стрес предизвикува епигенетски промени кои влијаат на менталното здравје. Медитеранската диета индуцира поволни епигенетски обрасци. Физичката активност го менува епигеномот на мускулните клетки. Епигенетските биомаркери може да откријат болест пред симптомите. Епигенетската терапија со лекови кои влијаат на метилација е во развој. Епигенетските лекови се користат за одредени видови рак како миелодиспластичен синдром. Епигенетските промени за време на бременост влијаат на здравјето на детето. Иднината носи епигенетска терапија за превенција и третман на хронични болести.`,
  170: `\n\nПРИМЕНА ВО МЕДИЦИНАТА. Пренаталното генетско тестирање еволуираше брзо. Неинвазивното пренатално тестирање од мајчина крв открива хромозомски абнормалности. NIPT скринингот за трисомија 21 (Даунов синдром) има висока точност. Носењето на генетски мутации како BRCA и CFTR може да се идентификува. Предимплантациската генетска дијагноза овозможува селекција на ембриони. Хорионската вилозност биопсија нуди дефинитивна дијагноза. Амниоцентезата од 15-20 гестациска недела е инвазивна дијагностика. Етичките дилеми вклучуваат избор врз основа на генетски карактеристики. Информираната согласност и генетското советување се задолжителни. Родителите имаат право да знаат и да не знаат за одредени наоди. Различни култури и религии имаат различни ставови. Трошокот за генетско тестирање паѓа, што го прави подостапно. Иднината носи проширен скрининг за повеќе генетски состојби. Секвенционирањето на целиот геном на новороденчиња се разгледува како идна скрининг алатка.`,

  // Cat 17: Farmakologija (171-175)
  171: `\n\nНОВИ ТЕРАПЕВТСКИ ОПЦИИ. ГЛП-1 рецептор агонистите се револуционерни лекови за дијабетес и дебелина. Семаглутидот (Оземпик, Вегови) имитира природен хормон кој регулира апетит. Забавувањето на гастрично празнење го намалува апетитот. Губењето на тежина е просечно 15% кај клиничките студии. Дозирањето започнува со ниска доза и постепено се зголемува. Гадење и повраќање се најчести несакани ефекти. Долгорочната безбедност се следи. Пероралната форма на семаглутид е достапна. Тиразепатид (Моуњаро) е двоен ГЛП-1 и ГИП агонист со уште поголема ефикасност. Ретардутнатид е троен агонист во фаза на клинички испитувања. Револуционерниот потенцијал на овие лекови го менува третманот на дијабетес и дебелина. Достапноста и високата цена се главни ограничувања. Иднината носи уште поефикасни комбинирани агонисти со помалку несакани ефекти.`,
  172: `\n\nНОВИ ПРИСТАПИ ВО ТЕРАПИЈАТА. МРНК технологијата се покажа како клучна за време на пандемијата. Вакцините на Фајзер/БиоНТек и Модерна користат МРНК. Брзината на развој на вакцина според нова цел е неколку недели. Имуниот систем произведува заштитни антитела и Т-клетки. МРНК вакцините се безбедни и високоефикасни. Миокардитисот е редок несакан ефект кај млади мажи. Бивалентните вакцини штитат од повеќе варијанти. МРНК технологијата сега се користи за развој на вакцини против рак и грип. Клиничките испитувања за МРНК вакцини против меланом и рак на бели дробови се во тек. Лабавиот студен ланец за складирање на МРНК вакцини е решен. МРНК вакцините може да се прилагодат на нови варијанти со едноставна промена на секвенцата. Револуцијата на МРНК технологијата отвори нови можности за персонализирана медицина. Хибридниот имунитет од вакцинација и прележана инфекција нуди најширока заштита.`,
  173: `\n\nДИЗАЈН НА ЛЕКОВИ. Откривањето на нови лекови се потпира на технологии како ДНК секвенционирање, хитс просес скрининг и структурна биологија. Цената за развој на нов лек е околу 1-2 милијарди долари. Клиничките испитувања поминуваат низ фази I, II и III. Фаза I го тестира безбедноста кај здрави волонтери. Фаза II го тестира ефектот и дозирањето кај пациенти. Фаза III ги споредува новиот лек со стандарден третман. Помалку од 10% од лековите достигнуваат одобрување. Вештачката интелигенција го забрзува откривањето на кандидати за лекови. Големите фармацевтски компании имаат обемни истражувачки капацитети. Биотехнолошките стартап компании се често извор на иновации. Патентите даваат ексклузивност 20 години. Регулативата на лекови од ФДА и ЕМА обезбедува безбедност и ефикасност. Иднината носи вештачка интелигенција за предвидување на безбедноста и ефикасноста на лековите пред клинички испитувања.`,
  174: `\n\nПРЕДИЗВИЦИ ВО ТЕРАПИЈАТА. Опиоидната криза резултираше од прекумерно препишување. Стапките на смртност од предозирање во САД достигнуваат 100.000 годишно. Не-опиоидни аналгетици како НСАИЛ и ацетаминофен се прва линија за болка. Опиоидите се резервирани за акутна и малигна болка. Насоките за препишување се построги. Налоксонот го враќа предозирањето со опиоиди. Фентанилот е илјада пати појак од морфин. Аналгетичката скала на СЗО води пристап кон болка. Габалергичните лекови како габапентин се користат за невропатска болка. Комбинацијата на различни механизми на дејство подобрува аналгезија со помалку несакани ефекти. Новите не-опиоидни аналгетици се во клинички испитувања. Едукацијата на лекарите за ризиците од опиоиди и алтернативните опции се интензивира. Зависноста од опиоиди бара мултидисциплинарен третман. Скринингот за ризик од зависност пред препишување станува стандардна пракса.`,
  175: `\n\nПЕРСОНАЛИЗИРАНИ ТЕРАПИИ. CAR T клеточната терапија е персонализирана имунотерапија за рак. Т-клетките од пациентот се инженеруваат да го препознаваат туморот. Т-клетките се генетски модифицирани со химерен антиген рецептор. CAR-T терапијата е одобрена за B-клеточна акутна лимфобластна леукемија и лимфом. Стапките на ремисија се 70-90% кај одредени видови рак. Цитокинскиот ослободителен синдром е сериозен несакан ефект. Невротоксичноста е исто така несакан ефект кој бара внимателно следење. Трошоците се високи, околу 400.000 долари по третман. Истражувањата прошируваат CAR-T за солидни тумори. Генската терапија со AAV вектори се користи за наследни болести. Неколку генски терапии се одобрени за ретки генетски болести. Новите апликации на генска терапија за хемофилија, мускулна дистрофија и спинална мускулна атрофија се во развој. Иднината носи персонализирани генски терапии базирани на специфичен генетски дефект.`,
};

(async () => {
  let count = 0;
  for (const [id, text] of Object.entries(additions)) {
    const r = await pool.query('UPDATE articles SET content = content || $1 WHERE id = $2', [text, id]);
    if (r.rowCount > 0) count++;
  }
  
  const {rows: stats} = await pool.query('SELECT MIN(LENGTH(content)) as mi, MAX(LENGTH(content)) as mx, ROUND(AVG(LENGTH(content))) as av FROM articles');
  const {rows: short} = await pool.query('SELECT COUNT(*) as c FROM articles WHERE LENGTH(content) < 3000');
  const {rows: total} = await pool.query('SELECT COUNT(*) as c FROM articles');
  
  console.log(`Expanded ${count} articles (out of ${total[0].c} total)`);
  console.log(`Chars - Min:${stats[0].mi} Max:${stats[0].mx} Avg:${stats[0].av}`);
  console.log(`Words ~ Min:${Math.round(stats[0].mi/6)} Max:${Math.round(stats[0].mx/6)} Avg:${Math.round(stats[0].av/6)}`);
  console.log(`Still under 3000ch: ${short[0].c}`);
  
  await pool.end();
})().catch(e => { console.error(e.message); process.exit(1); });

